StringMap tmpMap;
String insKey = tools.getPrimaryPage().getString(".pyWorkObjectInsKey");
if(!"".equals(insKey)){
  String workCls = tools.getPrimaryPage().getString("pyWorkObjectClassName");
  tmpMap= pega_processengine_workutilities.pxGetTopLevelCoverKeyAndClass(workCls,insKey);
  tools.getPrimaryPage().putString(".pyDependencyAncestorKey",tmpMap.getString("pzInsKey"));
}

HashStringMap keys = new HashStringMap();
keys.putString("pxObjClass","Rule-Obj-Activity");
keys.putString("pyClassName","Work-Cover-");
keys.putString("pyActivityName","pyGetCaseInfo");
ParameterPage cp=tools.getParameterPage();
String CoverInsKey=myStepPage.getString("pxCoverInsKey");
if(!CoverInsKey.equals(""))
{
	ClipboardPage coverPage=tools.findPageByHandle(CoverInsKey);
	if(coverPage!=null)
	{
	   tools.getPrimaryPage().putString(".pyDependencyAncestorKey",coverPage.getString(".pzInsKey"));
        	}
	else
	{	
            cp.putParamValue("pyKey",CoverInsKey);
            cp.putParamValue("pyPageName","TemporaryPage");
            tools.doActivity(keys,null,cp);
            ClipboardPage TemporaryPage=tools.findPage("TemporaryPage");
            if(TemporaryPage!=null && TemporaryPage.getInteger("pxResultCount")>0)
            {
		ClipboardPage cPage = TemporaryPage.getProperty("pxResults(1)").getPageValue();
		tools.getPrimaryPage().putString(".pyDependencyAncestorKey",cPage.getString(".pzInsKey"));
            }
            TemporaryPage.removeFromClipboard();
	}
}
